arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/bash
case "$1" in
  *Username*) echo "x-access-token" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/askpass.sh && cd /tmp/wt-rachel && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/rachel 2>&1 | tail -5
